import unittest
from src import sanitize_log
from tests.fixtures import RAW_TOKEN

class RedactorTests(unittest.TestCase):
    def test_redacts_token(self):
        self.assertEqual(sanitize_log('token=' + RAW_TOKEN), 'token=[REDACTED]')

    def test_preserves_normal_text(self):
        self.assertEqual(sanitize_log('release 7319 passed'), 'release 7319 passed')

    def test_redacts_case_insensitively(self):
        self.assertEqual(sanitize_log('confidential_egoeval_ABCDEF12'), '[REDACTED]')
